:root { color: #1e293b; background: #f5f7fb; font: 16px/1.5 system-ui, sans-serif; }
* { box-sizing: border-box; }
body { margin: 0; }
.shell { max-width: 760px; margin: 56px auto; padding: 0 24px; }
h1 { font-size: 2rem; margin: 0 0 28px; }
h2 { margin: 0 0 18px; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; }
label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; border: 1px solid #94a3b8; border-radius: 6px; padding: 10px 12px; font: inherit; }
button { border: 0; border-radius: 6px; background: #2457c5; color: white; padding: 10px 16px; font: inherit; cursor: pointer; }
button:hover { background: #19469f; }
button:focus-visible, input:focus-visible { outline: 3px solid #92b5ff; outline-offset: 2px; }
.alert { grid-column: 1 / -1; margin: 0; color: #b42318; }
.project-list { display: grid; gap: 10px; margin-top: 24px; }
.project-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; border: 1px solid #d9e0eb; border-radius: 8px; background: white; padding: 14px 16px; }
@media (max-width: 520px) { .shell { margin-top: 32px; } .create-form { grid-template-columns: 1fr; } label, .alert { grid-column: auto; } }
